```js
function requireAuth(req, res, next) {
  const token = req.get('authorization')?.replace(/^Bearer\s+/i, '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    req.user = verifyJwt(token); // your verifier
    next();
  } catch {
    return res.status(401).json({ error: 'unauthorized' });
  }
}

app.get('/users', requireAuth, (req, res) => {
  // Only return email if the caller is an admin or the user themselves
  const isAdmin = req.user.roles?.includes('admin');
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ].map(u => isAdmin ? u : { id: u.id, name: u.name });
  res.json(users);
});
```

---

### 🟠 5. No CORS policy declared

**OWASP A05 – Security Misconfiguration**

Without explicit CORS configuration, browsers use same-origin defaults. That's safer than `*`, but the moment someone adds `cors()` carelessly, you'll get `Access-Control-Allow-Origin: *` with credentials. Set policy explicitly.

**Fix:**
```js
const cors = require('cors');
app.use(cors({
  origin: ['https://app.example.com'],   // allow-list, never '*'
  methods: ['GET'],
  credentials: true,
  maxAge: 600,
}));
```

